#include <iostream>
#include <sstream>
#include <string>
#include <iomanip>

std::string representar(int cantidad) {
    std::ostringstream texto;
    texto << "dec=" << std::dec << cantidad << ";hex=" << std::hex << cantidad
        << ";oct=" << std::oct << cantidad;
    return texto.str();
}

int main() {
    std::cout << std::hex;
    std::string primero = representar(10);
    std::string segundo = representar(20);
    std::cout << primero << "\n" << segundo << "\n" << 26;
    return 0;
}

